namespace ohao::display {

std::array<float, 3> displayPixelGpu(std::array<float, 3> radiance, float exposure, uint32_t curve) {
    Vector<float, 4> io[2]{};
    io[0].x = radiance[0];
    io[0].y = radiance[1];
    io[0].z = radiance[2];
    io[0].w = exposure;
    io[1].w = std::bit_cast<float>(curve);
    GlobalParams_0 globals{};
    globals.io_0.data = io;
    globals.io_0.count = 2;
    ComputeVaryingInput range{};
    range.startGroupID = {0, 0, 0};
    range.endGroupID = {1, 1, 1};
    ::run(&range, nullptr, &globals);
    return {io[1].x, io[1].y, io[1].z};
}

} // namespace ohao::display
